"use strict";(globalThis.webpackChunkgrc||=[]).push([[21749],{6626(e){e.exports=JSON.parse('{"citeKey":"yildirim2025wisio","slug":"yildirim-2025-wisio-45f7","title":"WisIO: Automated I/O Bottleneck Detection with Multi-Perspective Views for HPC Workflows","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The 39th ACM International Conference on Supercomputing (ICS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3721145.3725742","abstract":"Modern HPC workloads involve large data transfers that can become bottlenecks. Existing analysis tools identify bottle- necks from per-file performance data but have limitations in parallelizability and rigid heuristic-based rules, necessitating an automated, efficient, and multi-perspective solution. We designed an automated tool, WisIO, that enables parallel and distributed analysis of multi-terabyte-scale workflow performance data. WisIO examines performance data from multiple perspectives, uses metric-driven bottleneck classifi- cation, and allows extensible mapping of bottlenecks to root causes. Experimental results demonstrate that WisIO\'s multi- perspective views substantially improve bottleneck coverage, showing an average increase of up to 805\xd7 when compared to analyzing performance data from a single perspective. In our performance evaluation, WisIO\'s metric-driven classification processed 340K bottlenecks per second, while its reasoning engine handled around 35K bottlenecks per sec- ond. In an analysis of five real-world HPC workloads, WisIO demonstrated up to 11\xd7 faster analysis time and identified up to 144x more bottlenecks compared to existing solutions.","hasAbstract":true,"lede":"Modern HPC workloads involve large data transfers that can become bottlenecks.","links":{"pdf":"https://grc.iit.edu/papers/2025/yildirim-2025-wisio-45f7.pdf"},"tags":["HPC","Workflows","I/O Analysis","I/O Bottleneck Detection","WisIO","LABIOS"],"_projectIds":["chronolog","labios","iowarp"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","labios","chronolog","wisio"],"memberAuthors":["yildirim-izzet","devarajan-hariharan","kougkas-anthony","sun-xian-he","mohror-kathryn"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"NSF","award":"OAC-2313154","projectId":"labios"},{"agency":"NSF","award":"OAC-2411318","projectId":"iowarp"},{"agency":"LLNL","award":"DE-AC52-07NA27344"}]}')}}]);